cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

extern "C" __global__
void sum_reduce_kernel(const half* __restrict__ input,
                       half* __restrict__ output,
                       int dim0, int dim1, int dim2,
                       int reduce_dim, int reduce_size) {
    // linear index of the output element (excluding reduced dim)
    int out_idx = blockIdx.x * blockDim.x + threadIdx.x;

    // total number of output elements (product of non‑reduced dims)
    int total_out = (reduce_dim == 0 ? 1 : dim0) *
                    (reduce_dim == 1 ? 1 : dim1) *
                    (reduce_dim == 2 ? 1 : dim2);

    if (out_idx >= total_out) return;

    // decode multi‑dimensional coordinates of the output element
    int i0 = 0, i1 = 0, i2 = 0;
    int tmp = out_idx;
    if (reduce_dim == 0) {                 // reducing over dim0
        i0 = 0;
        i1 = tmp / dim2;
        i2 = tmp % dim2;
    } else if (reduce_dim == 1) {          // reducing over dim1
        i1 = 0;
        i0 = tmp / dim2;
        i2 = tmp % dim2;
    } else {                               // reducing over dim2
        i2 = 0;
        i0 = tmp / dim1;
        i1 = tmp % dim1;
    }

    // sum over the reduced dimension
    float sum = 0.0f;
    for (int r = 0; r < reduce_size; ++r) {
        int in_offset;
        if (reduce_dim == 0) {
            // offset = r * dim1 * dim2 + i1 * dim2 + i2
            in_offset = ((r) * dim1 * dim2) + (i1 * dim2) + i2;
        } else if (reduce_dim == 1) {
            // offset = i0 * dim1 * dim2 + r * dim2 + i2
            in_offset = (i0 * dim1 * dim2) + (r * dim2) + i2;
        } else {
            // offset = i0 * dim1 * dim2 + i1 * dim2 + r
            in_offset = (i0 * dim1 * dim2) + (i1 * dim2) + r;
        }
        sum += __half2float(input[in_offset]);
    }

    // write result back as fp16
    output[out_idx] = __float2half(sum);
}
'''

# Compile the kernel
_sum_reduce_mod = load_inline(
    name='sum_reduce_cuda',
    cpp_sources='',
    cuda_sources=cuda_src,
    functions=['sum_reduce_kernel'],
    verbose=False,
)

