def sum_reduce_fp16(x: torch.Tensor, dim: int) -> torch.Tensor:
    """
    Reduce `x` (fp16, CUDA) along `dim` using the custom CUDA kernel.
    Keeps the reduced dimension (size 1) to match torch.sum(..., keepdim=True).
    """
    if not x.is_cuda:
        raise RuntimeError("Input tensor must be CUDA.")
    if x.dtype != torch.float16:
        raise RuntimeError("Input tensor must be torch.float16.")
    if x.dim() != 3:
        raise NotImplementedError("Kernel currently supports 3‑D tensors only.")

    d0, d1, d2 = x.shape
    dims = [d0, d1, d2]
    reduce_size = dims[dim]

    # output shape with keepdim=True
    out_shape = list(x.shape)
    out_shape[dim] = 1
    out = torch.empty(out_shape, device=x.device, dtype=torch.float16)

    # total number of output elements (product of non‑reduced dims)
    total_out = (dims[0] if dim != 0 else 1) * \
                (dims[1] if dim != 1 else 1) * \
                (dims[2] if dim != 2 else 1)

    threads = 256
    blocks = (total_out + threads - 1) // threads

    _sum_reduce_mod.sum_reduce_kernel(
        (blocks,),
        (threads,),
        (
            x.data_ptr(),
            out.data_ptr(),
            d0,
            d1,
            d2,
            dim,
            reduce_size,
        ),
        stream=torch.cuda.current_stream().cuda_stream,
    )

    return out

