    # match reference shapes but use fp16 and CUDA
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    x = torch.rand(batch_size, dim1, dim2, device='cuda', dtype=torch.float16)
    return [x]

def get_init_inputs():
    # same reduce dimension as reference
    return [1]
